@push('scripts')<script>$(function(){var t=$('#uoms-table'),x=$.fn.dataTable.render.text(),s=$('#uom-status-filter');var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.is_active=s.val();}},buttons:[window.erpExcelButton(t)],order:[[0,'asc']],columns:[{data:'code',render:x.display},{data:'name',render:x.display},{data:'decimal_places',className:'text-end',render:x.display},{data:'status_label',render:x.display},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,z,r){return z==='display'&&r.edit_url?'<a class="btn btn-sm btn-outline-dark" href="'+x.display(r.edit_url)+'"><i class="bx bx-edit me-1" aria-hidden="true"></i>แก้ไข</a>':'';}}]}));s.on('change',function(){dt.ajax.reload();});$('#uom-filter-reset').on('click',function(){s.val('1').trigger('change');});});</script>@endpush
